-- ---------------------------------------------------------------- Hand-written

-- CHECK constraints (DATA_DICTIONARY §1).
ALTER TABLE "users"
    ADD CONSTRAINT "users_display_name_length" CHECK (char_length("display_name") BETWEEN 1 AND 60),
    ADD CONSTRAINT "users_status_values" CHECK ("status" IN ('active', 'locked', 'suspended', 'pending_deletion')),
    ADD CONSTRAINT "users_pending_deletion_has_request" CHECK ("status" <> 'pending_deletion' OR "deletion_requested_at" IS NOT NULL);

ALTER TABLE "user_preferences"
    ADD CONSTRAINT "user_preferences_theme_values" CHECK ("theme" IN ('light', 'dark', 'system')),
    ADD CONSTRAINT "user_preferences_week_start_range" CHECK ("week_start" BETWEEN 0 AND 6);

ALTER TABLE "auth_identities"
    ADD CONSTRAINT "auth_identities_provider_values" CHECK ("provider" IN ('google'));

ALTER TABLE "verification_tokens"
    ADD CONSTRAINT "verification_tokens_new_email_only_for_email_change" CHECK (("type" = 'email_change') = ("new_email" IS NOT NULL));

-- Partial and trigram indexes (INDEXING_STRATEGY).
-- Daily account:purge job.
CREATE INDEX "users_deletion_requested_at_pending_idx" ON "users"("deletion_requested_at") WHERE "status" = 'pending_deletion';
-- Admin user search (F-ADMIN-001).
CREATE INDEX "users_display_name_trgm_idx" ON "users" USING gin (lower("display_name") gin_trgm_ops);
-- "Your devices" list (F-AUTH-007).
CREATE INDEX "user_sessions_user_id_last_used_at_active_idx" ON "user_sessions"("user_id", "last_used_at" DESC) WHERE "revoked_at" IS NULL;
-- Invalidate older tokens on reissue.
CREATE INDEX "verification_tokens_user_id_type_open_idx" ON "verification_tokens"("user_id", "type") WHERE "consumed_at" IS NULL;
